function longestZigZag(root) {
  let best = 0;

  // leftRun: longest zigzag ending at node whose last step went left.
  // rightRun: longest zigzag ending at node whose last step went right.
  function dfs(node, leftRun, rightRun) {
    if (!node) {
      return;
    }
    best = Math.max(best, leftRun, rightRun);
    // Stepping left continues a path whose last step went right.
    dfs(node.left, rightRun + 1, 0);
    // Stepping right continues a path whose last step went left.
    dfs(node.right, 0, leftRun + 1);
  }

  dfs(root, 0, 0);
  return best;
}

