function longestZigZag(root) {
  let best = 0;
  const stack = [root];
  while (stack.length) {
    const start = stack.pop();
    if (!start) continue;
    stack.push(start.left, start.right);
    for (const first of ['left', 'right']) {
      let node = start, side = first, steps = 0;
      while (node[side]) {
        node = node[side];
        steps++;
        side = side === 'left' ? 'right' : 'left';
      }
      best = Math.max(best, steps);
    }
  }
  return best;
}

