function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const count = size === 'large' ? 850 + pick(130) : 1 + pick(14);
  const shape = pick(3); // 0: random, 1: zigzag-heavy, 2: long chains
  const nodes = [{ val: 1 + pick(100), left: null, right: null }];
  let last = nodes[0], lastSide = rand() < 0.5 ? 'left' : 'right';
  while (nodes.length < count) {
    const node = { val: 1 + pick(100), left: null, right: null };
    let parent, side;
    if (shape === 1 && rand() < 0.85) {
      parent = last;
      side = lastSide === 'left' ? 'right' : 'left';
    } else if (shape === 2 && rand() < 0.85) {
      parent = last;
      side = lastSide;
    } else {
      parent = nodes[pick(nodes.length)];
      side = rand() < 0.5 ? 'left' : 'right';
    }
    if (parent[side]) {
      last = nodes[pick(nodes.length)];
      lastSide = rand() < 0.5 ? 'left' : 'right';
      continue;
    }
    parent[side] = node;
    nodes.push(node);
    last = node;
    lastSide = side;
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
